package com.perkvault.app;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import org.json.*;import java.time.*;import java.util.regex.*;
class Capture {
 static void show(Context c,String raw,Runnable done){boolean overlay=c instanceof Bubble;LinearLayout l=new LinearLayout(c);l.setOrientation(1);l.setPadding(24,12,24,12);EditText source=field(c,l,"Source app"),brand=field(c,l,"Brand / voucher name"),code=field(c,l,"Coupon code"),expiry=field(c,l,"Expiry YYYY-MM-DD (optional)"),details=field(c,l,"Offer / balance / points / category");Spinner type=new Spinner(c);type.setAdapter(new ArrayAdapter<>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"Coupon","Gift card","Loyalty"}));l.addView(type);Button paste=new Button(c);paste.setText("Paste coupon code");l.addView(paste);paste.setOnClickListener(v->{ClipboardManager cm=(ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);if(cm.hasPrimaryClip())code.setText(cm.getPrimaryClip().getItemAt(0).coerceToText(c));});Button date=new Button(c);date.setText("Choose expiry date");l.addView(date);date.setOnClickListener(v->{LocalDate n=LocalDate.now();DatePickerDialog p=new DatePickerDialog(c,(x,y,m,d)->expiry.setText(LocalDate.of(y,m+1,d).toString()),n.getYear(),n.getMonthValue()-1,n.getDayOfMonth());if(overlay)p.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);p.show();});if(raw!=null&&!raw.trim().isEmpty()){details.setText(raw);Matcher m=Pattern.compile("\\b[A-Z0-9]{4,}(?:-[A-Z0-9]{3,})+\\b").matcher(raw);if(m.find())code.setText(m.group());Matcher dt=Pattern.compile("\\b\\d{4}-\\d{2}-\\d{2}\\b").matcher(raw);if(dt.find())expiry.setText(dt.group());for(String s:new String[]{"Paytm","PhonePe","Google Pay","CRED","Amazon Pay"})if(raw.toLowerCase().contains(s.toLowerCase()))source.setText(s);for(String s:new String[]{"Lenskart","Myntra","Swiggy","Zomato","AJIO","Amazon","Flipkart"})if(raw.toLowerCase().contains(s.toLowerCase()))brand.setText(s);}
 ScrollView scroll=new ScrollView(c);scroll.addView(l);AlertDialog d=new AlertDialog.Builder(c).setTitle("Quick save reward").setView(scroll).setPositiveButton("Save",null).setNegativeButton("Cancel",null).setNeutralButton("Save & Add Another",null).create();if(overlay)d.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);d.setOnDismissListener(x->done.run());d.show();final boolean[] another={false};d.getButton(-3).setOnClickListener(v->{another[0]=true;d.getButton(-1).performClick();another[0]=false;});d.getButton(-1).setOnClickListener(v->{String b=brand.getText().toString().trim(),k=code.getText().toString().trim(),e=expiry.getText().toString().trim();if(b.isEmpty()){brand.setError("Required");return;}if(!e.isEmpty())try{LocalDate.parse(e);}catch(Exception ex){expiry.setError("Use YYYY-MM-DD");return;}if(Store.duplicate(c,k)){code.setError("Already saved");return;}try{JSONObject o=new JSONObject();o.put("brand",b);o.put("source",source.getText().toString());o.put("code",k);o.put("expiry",e);o.put("details",details.getText().toString());o.put("type",type.getSelectedItem().toString());o.put("used",false);o.put("created",LocalDate.now().toString());JSONArray a=Store.read(c);a.put(o);Store.write(c,a);Reminder.schedule(c);if(another[0]){brand.setText("");code.setText("");expiry.setText("");details.setText("");brand.requestFocus();Toast.makeText(c,"Saved",0).show();}else d.dismiss();}catch(Exception ex){Toast.makeText(c,"Could not save",0).show();}});}
 static EditText field(Context c,LinearLayout l,String hint){EditText e=new EditText(c);e.setHint(hint);l.addView(e);return e;}
}
